// He walks in at the door (8), down the left aisle and along the 4th row to his seat (SEAT_MS from settling). At the intermission he and the\n  // friend go back out (TRIP.out), the camera switches to the lobby (CAM-39), they queue at the snack bar, buy, and come back in (TRIP.sit).\n  const SEAT_MS = 9000, TRIP = {out: 10000, sw1: 12000, buy: 46000, lobby: 80000, sw2: 82000, sit: 96000};\n  function filmBreakK(){ if (!FILM_L || !FILM) return null; const b = FILM_L.items.find(x => x.kind === 'break'); return b ? NOW() - FILM.at - b.t0 : null; }\n  function tripNow(){\n    if (DREAMING || actor.loc !== 'cinema' || actor.travelling || actor.hidden || actor.pending || forceLoc) return null;\n    const k = filmBreakK(); if (k == null || k < 0 || k >= TRIP.sit) return null;\n    return {k, phase: k < TRIP.out ? 'out' : k < TRIP.sw1 ? 'sw' : k < TRIP.lobby ? 'lobby' : k < TRIP.sw2 ? 'sw' : 'in'};\n  }\n  const hasSnacks = () => { const k = filmBreakK(); return k != null && k >= TRIP.buy && actor.loc === 'cinema'; };\n  // a point on the way between a seat in the 4th row and the door: u = 0 at the seat, 1 at the door\n  function cinWay(seatX, u){ const rowY = CIN_ROWS[3] - 14, aisle = 4, d1 = seatX - aisle, d2 = 14, all = d1 + d2, s = u * all;\n    if (s <= d1) return {x: seatX - s, y: rowY, face: -1}; const v = (s - d1) / d2; return {x: aisle + v * 4, y: rowY - v * 10, face: -1}; }\n  function cinWalk(){   // null, or where he and the friend are while walking to or from their seats\n    const tr = tripNow(), since = actor.settledAt != null ? NOW() - actor.settledAt : 1e9;\n    let u = null, out = false;\n    if (tr && tr.phase === 'out'){ u = tr.k / TRIP.out; out = true; }\n    else if (tr && tr.phase === 'in'){ u = 1 - (tr.k - TRIP.sw2) / (TRIP.sit - TRIP.sw2); }\n    else if (since < SEAT_MS && actor.loc === 'cinema'){ u = 1 - since / SEAT_MS; }\n    if (u == null) return null; u = Math.max(0, Math.min(1, u));\n    const me = CIN_SEAT_X0 + 6 * CIN_SEAT_W + 1, fr = me + CIN_SEAT_W;   // the friend sits further along: in first, out last\n    const ish = cinWay(me, out ? Math.max(0, Math.min(1, u * 1.15)) : Math.max(0, Math.min(1, u * 1.15 - .15)));\n    const frd = cinWay(fr, out ? Math.max(0, u * 1.15 - .15) : Math.min(1, u * 1.1));\n    if (!out){ ish.face = 1; frd.face = 1; }\n    return {ish, frd, carry: hasSnacks()};\n  }\n  // the friend's place while they walk with him by the clock: keep the companion controller in step, so it never walks them in from a door\n  function compAt(id, look, x){ if (comp.id === id && comp.mode !== 'out'){ comp.x = x; comp.tx = x; comp.mode = 'here'; } return wantComp({id, look, x, kind:'seat'}); }\n  // in the lobby: from the auditorium door to the counter, buying, and back (k from the switch)\n  function lobbyTrip(t){\n    const tr = tripNow(); if (!tr || tr.phase !== 'lobby') return;\n    const k = tr.k - TRIP.sw1, len = TRIP.lobby - TRIP.sw1, door = LOBBY_DOOR - 6, at = LOBBY_COUNTER - 6;\n    const walkIn = 14000, walkOut = len - 16000, carry = tr.k >= TRIP.buy;\n    let x, pose = 'walk', face = -1;\n    if (k < walkIn) x = door + (at - door) * (k / walkIn);\n    else if (k < walkOut){ x = at; pose = 'back'; }\n    else { x = at + (door - at) * Math.min(1, (k - walkOut) / 14000); face = 1; }\n    const a = actor.action, cl = actor.with && companionLook(a), fx = pose === 'back' ? x + 16 : x + (face < 0 ? 14 : -14);\n    zAdd(88, () => {\n      if (cl && compAt(actor.with, cl, fx)){ markHead(actor.with, fx, 66); person(cl, fx, 66, t + 300, pose === 'back' ? {fid: SAY.who === actor.with ? undefined : 'turn', talkPhase: SAY.who === actor.with} : {walk: true, face}); if (carry && pose !== 'back') cooolaCup(fx + (face > 0 ? 8 : -1), 78); }\n      drawIshai(pose === 'back' && SAY.who === 'ishai' ? 'talking' : pose, x, 66, t, {face}); markHead('ishai', x, 66);\n      if (carry){ popcornBucket(x + (face > 0 ? 8 : -3), 76); cooolaCup(x + (face > 0 ? -2 : 9), 78); }\n    });\n  }\n  // the auditorium (C