    const base = cur.title; cur.of = 2; cur.part = 1; cur.title = base + ", Part 1";
    c.queue.splice(1, 0, { id: cur.id + "-2", title: base + ", Part 2", wiki: cur.wiki, strand: cur.strand, part: 2, of: 2 });
