    m.state = "none"; await memberPut(env, m, now);
    await memberSay(env, m.id, "green", `GREEN LIGHT (test): ${name} would join the show as ${w.title}, first scene ${audWhen(at)}. It's a test, so nothing was booked.`, false, now);
